def _safe_float(value: Any) -> Optional[float]:
if value is None:
return None
try:
numeric = float(value)
except Exception:
return None
if math.isnan(numeric) or math.isinf(numeric):
return None
return numeric
def _normalize_json_value(value: Any) -> Any:
if isinstance(value, dict):
