def compute_metadata_alignment(
values: pd.Series,
metadata: MetadataContext,
) -> Dict[str, Any]:
"""Compute deterministic paired-metadata alignment metrics for one feature."""
result = {
"metadata_max_abs_spearman": 0.0,
"metadata_best_spearman_field": None,
"metadata_max_anova_f": 0.0,
"metadata_best_anova_field": None,
"metadata_max_eta_squared": 0.0,
"metadata_best_eta_field": None,
"metadata_max_classifier_auc": 0.5,
"metadata_best_classifier_field": None,
"metadata_alignment_score": 0.0,
}
if metadata.dataframe is None:
return result
data = metadata.dataframe
if len(values) != len(data):
raise ValueError("Feature values and metadata rows must be aligned.")
for field in metadata.continuous_fields:
field_values = pd.to_numeric(data[field], errors="coerce")
mask = values.notna() & field_values.notna()
if mask.sum() < 3:
continue
x = values[mask]
y = field_values[mask]
if x.nunique() < 2 or y.nunique() < 2:
continue
corr, _ = stats.spearmanr(x, y, nan_policy="omit")
if pd.notna(corr) and abs(float(corr)) > result["metadata_max_abs_spearman"]:
result["metadata_max_abs_spearman"] = abs(float(corr))
result["metadata_best_spearman_field"] = field
for field in metadata.categorical_fields:
field_values = data[field]
mask = values.notna() & field_values.notna()
if mask.sum() < 3:
continue
grouped = []
x = values[mask]
y = field_values[mask]
for _, group_values in x.groupby(y):
if len(group_values) > 0:
grouped.append(group_values.to_numpy())
if len(grouped) < 2:
continue
try:
f_stat, _ = stats.f_oneway(*grouped)
except Exception:
continue
if pd.isna(f_stat):
continue
total_mean = float(np.mean(x))
ss_between = 0.0
ss_total = float(np.sum((x - total_mean) ** 2))
if ss_total > 0:
for group in grouped:
ss_between += len(group) * (float(np.mean(group)) - total_mean) ** 2
eta_sq = max(0.0, min(1.0, ss_between / ss_total))
else:
eta_sq = 0.0
if float(f_stat) > result["metadata_max_anova_f"]:
result["metadata_max_anova_f"] = float(f_stat)
result["metadata_best_anova_field"] = field
if eta_sq > result["metadata_max_eta_squared"]:
result["metadata_max_eta_squared"] = eta_sq
result["metadata_best_eta_field"] = field
classifier_auc = _linear_classifier_score(x.to_numpy(dtype=float), y.to_numpy())
if classifier_auc > result["metadata_max_classifier_auc"]:
result["metadata_max_classifier_auc"] = float(classifier_auc)
result["metadata_best_classifier_field"] = field
# Map classifier AUC (chance=0.5) onto a [0, 1] alignment contribution.
classifier_alignment = max(0.0, (float(result["metadata_max_classifier_auc"]) - 0.5) * 2.0)
result["metadata_alignment_score"] = max(
result["metadata_max_abs_spearman"],
result["metadata_max_eta_squared"],
classifier_alignment,
)
return result

"""Batched LLM review for ambiguous semantic redundancy."""
from __future__ import annotations
import json
from typing import Any, Dict, List
from langchain_core.messages import HumanMessage, SystemMessage
from config import make_chat_llm
class LLMRedundancyReviewer:
"""Review ambiguous redundancy groups in batched LLM calls."""
def __init__(self) -> None:
self.llm = make_chat_llm(temperature=0)
self.max_chars_per_chunk = 24000
def review_groups(self, groups: List[Dict[str, Any]]) -> Dict[str, Any]:
"""Review connected groups and return parsed resolutions."""
if not groups:
return {"success": True, "groups": [], "chunks": []}
chunks = self._chunk_groups(groups)
all_resolutions: List[Dict[str, Any]] = []
chunk_records: List[Dict[str, Any]] = []
for chunk_index, chunk in enumerate(chunks, start=1):
payload = json.dumps(chunk, indent=2, ensure_ascii=False)
chunk_record: Dict[str, Any] = {
"chunk_index": chunk_index,
"group_count": len(chunk),
"input_group_ids": [group["group_id"] for group in chunk],
"request_payload": chunk,
}
try:
response = self.llm.invoke(
[
SystemMessage(content=self._system_prompt()),
HumanMessage(content=self._user_prompt(payload)),
]
)
content = response.content if hasattr(response, "content") else str(response)
parsed = self._parse_response(content)
chunk_record["raw_response"] = content
chunk_record["parsed_response"] = parsed
all_resolutions.extend(parsed)
except Exception as exc:
chunk_record["error"] = repr(exc)
return {
"success": False,
"error": repr(exc),
"groups": [],
"chunks": chunk_records + [chunk_record],
}
chunk_records.append(chunk_record)
return {"success": True, "groups": all_resolutions, "chunks": chunk_records}
def _chunk_groups(self, groups: List[Dict[str, Any]]) -> List[List[Dict[str, Any]]]:
chunks: List[List[Dict[str, Any]]] = []
current: List[Dict[str, Any]] = []
current_size = 0
for group in groups:
serialized = json.dumps(group, ensure_ascii=False)
if current and current_size + len(serialized) > self.max_chars_per_chunk:
chunks.append(current)
current = []
current_size = 0
current.append(group)
current_size += len(serialized)
if current:
chunks.append(current)
return chunks
def _system_prompt(self) -> str:
return (
"You are reviewing feature redundancy decisions for microscopy feature engineering.\n"
"Be conservative: prefer keeping the older or numerically stronger feature unless the new feature is clearly better or explicitly complementary.\n"
"Return ONLY valid JSON.\n"
"For each group return an object with keys: group_id, decision, keep_feature_ids, drop_feature_ids, rationale.\n"
"Allowed decision values: keep_old, keep_new, keep_both.\n"
"Use keep_both only when the features are genuinely complementary and should coexist."
)
def _user_prompt(self, payload: str) -> str:
return (
"Review the following ambiguous redundancy groups.\n"
"Each group already passed a deterministic pre-screen and needs a conservative semantic decision.\n"
"Groups:\n"
f"{payload}\n"
)
def _parse_response(self, content: str) -> List[Dict[str, Any]]:
text = content.strip()
if text.startswith("```"):
lines = [line for line in text.splitlines() if not line.strip().startswith("```")]
text = "\n".join(lines).strip()
if not text:
return []
try:
parsed = json.loads(text)
except json.JSONDecodeError:
start = text.find("[")
end = text.rfind("]")
if start == -1 or end == -1:
raise
parsed = json.loads(text[start : end + 1])
if isinstance(parsed, dict):
parsed = [parsed]
if not isinstance(parsed, list):
raise ValueError("LLM redundancy review must return a JSON list.")
return parsed
